    name: { de: "Bastion der Stadtmauer", hu: "Várfal-bástya", ro: "Bastionul zidului de apărare", en: "Bastion of the Vilnius Defensive Wall"},
    image: "/poi-images/lithuania-vilnius-bastion-landmarks-v2.webp",
